<script setup>import{inject}from'vue';const s=inject('planAdmin');const date=v=>v?new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(v)):'-';</script><template><section class="admin-card"><div class="card-heading"><div><h2>Subscriptions</h2><p class="text-sm text-slate-500">Clinics currently associated with this plan.</p></div></div><div class="table-wrap"><table><thead><tr><th>Clinic</th><th>Status</th><th>Started</th><th>Trial Ends</th><th>Renewal</th><th>Members</th><th>Actions</th></tr></thead><tbody><tr v-for="item in s.subscriptions.value" :key="item.id"><td class="font-semibold">{{item.tenant_name}}</td><td class="capitalize">{{item.status}}</td><td>{{date(item.created_at)}}</td><td>{{date(item.trial_ends_at)}}</td><td>Not recorded</td><td>{{item.members_count}}</td><td><RouterLink class="back-link" :to="{name:'admin.clinics.show',params:{id:item.tenant_id}}">View Clinic</RouterLink></td></tr></tbody></table><p v-if="!s.subscriptions.value.length" class="empty-state">No clinics use this plan.</p></div></section></template>
